<?php
namespace App\Models;
use Illuminate\Database\Eloquent\{Builder,Model,SoftDeletes};
class TransportRoute extends Model {use SoftDeletes; protected $fillable=['company_id','code','name','description','route_type','origin','destination','estimated_start_time','estimated_arrival_time','vehicle_id','default_driver_id','default_monitor_id','status','created_by','updated_by']; public function scopeForCompany(Builder $q,int $id):Builder{return $q->where('company_id',$id);} public function vehicle(){return $this->belongsTo(TransportVehicle::class,'vehicle_id');} public function driver(){return $this->belongsTo(TransportPerson::class,'default_driver_id');} public function monitor(){return $this->belongsTo(TransportPerson::class,'default_monitor_id');} public function stops(){return $this->hasMany(TransportRouteStop::class)->orderBy('stop_order');} public function passengers(){return $this->belongsToMany(TransportPassenger::class,'transport_route_passengers')->withPivot(['transport_route_stop_id','direction','valid_from','valid_until','status'])->withTimestamps();}}
